/* ============ Yaşayan dünya: duruma bağlı yüzlerce rastgele olay (kompakt tanım + şablonlar) ============ */
const EV3=[];
/* etki uygulayıcı: m para, f takipçi, hp mutluluk, hl sağlık, sk yetenek, lk görünüş, heat polis, yak partner yakınlık, fam aile, rep itibar */
function evFx(e,msg,k){if(!e)e={};if(e.m){S.money+=e.m}if(e.f){S.fol=Math.max(0,Math.round(S.fol+e.f))}if(e.fp){S.fol=Math.max(0,Math.round(S.fol*(1+e.fp)))}if(e.hp)add('happy',e.hp);if(e.hl)add('health',e.hl<0?Math.round(e.hl*.6):e.hl);if(e.sk)S.skill=clamp(S.skill+e.sk);if(e.lk)S.looks=clamp((S.looks||50)+e.lk);
 if(e.heat){jcInit();S.cr.heat=clamp(S.cr.heat+e.heat)}if(e.yak&&S.partner)S.partner.yak=clamp(S.partner.yak+e.yak);if(e.pot){const s=released().sort((a,b)=>b.ra-a.ra||b.id-a.id)[0];if(s)s.pot*=e.pot}if(e.months)S.months=Math.max(0,S.months+e.months);if(e.fn)e.fn();
 calcFame();if(msg)log(msg,k||(e.m>0||e.f>0||e.hp>0?'good':e.m<0||e.hp<0||e.hl<0?'bad':'dim'))}
/* seçim: {t, ok, bad, p, lo, lb} → p olasılıkla ok uygulanır (lo mesajı), yoksa bad (lb) */
function evCh(c){return {t:c.t,fn:p=>{const T=s=>{s=typeof s==='function'?s(p):s;return s?cap1(F(s)):s};if(c.p!=null&&!(S.star&&c.star)){if(ch(c.p))evFx(c.ok,T(c.lo));else evFx(c.bad,T(c.lb))}else evFx(c.ok,T(c.lo))}}}
function E(o){EV3.push(o);EVENTS.push({id:o.id,min:o.min||0,max:o.max,once:!!o.once,c:()=>!(S.cr&&S.cr.jail)&&(!o.c||o.c()),gen:o.gen,title:o.t,text:p=>cap1(typeof o.x==='function'?o.x(p):F(o.x)),ch:o.ch.map(evCh)})}
/* yardımcılar */
const V={art:()=>pick((S.rivals&&S.rivals.length?S.rivals.map(r=>r.name):[]).concat(ARTISTS2)),fr:()=>{const f=S.friends.filter(x=>x.yak>=30);return f.length?pick(f).name.split(' ')[0]:'bir arkadaşın'},city:()=>pick(['Ankara','İzmir','Bursa','Antalya','Adana','Trabzon','Eskişehir','Konya','Gaziantep','Samsun']),brand:()=>pick(BRANDS),mom:()=>'annen',dad:()=>'baban',
 pn:()=>S.partner?S.partner.name.split(' ')[0]:'sevgilin',kid:()=>S.kids&&S.kids.length?pick(S.kids).name.split(' ')[0]:'çocuğun',song:()=>{const r=released();return r.length?'"'+pick(r).t+'"':'şarkın'},big:()=>{const r=released().sort((a,b)=>b.total-a.total)[0];return r?'"'+r.t+'"':'şarkın'},
 venue:()=>pick(['Kadıköy\'de bir bar','Beyoğlu\'nda bir kulüp','Beşiktaş\'ta bir kafe','Bebek\'te bir restoran','Nişantaşı\'nda bir mağaza','metroda','havalimanında','AVM\'de','sahilde','benzinlikte','pazarda','kuaförde','taksi de','vapurda'])};
const cap1=s=>s?s[0].toUpperCase()+s.slice(1):s;
const F=(s)=>s.replace(/\{(\w+)\}/g,(m,k)=>V[k]?V[k]():m);
const fam=t=>S.fame>=t,famL=t=>S.fame<t,hasP=()=>!!S.partner,married=()=>S.partner&&S.partner.st==='eş',kids=()=>S.kids&&S.kids.length>0,rich=t=>S.money>=t,poor=()=>S.money<20000,rel=()=>released().length>0,job=()=>!!S.job,uni=()=>S.sch&&S.sch.uni&&S.sch.uni!=='yok'&&S.sch.uniLeft>0,hs=()=>S.sch&&S.sch.hs&&!S.sch.hsDone,abroad=()=>S.ct&&S.ct!=='tr',hasLab=()=>!!S.lab,con=()=>!!S.contract,heat=t=>S.cr&&S.cr.heat>=t,rap=()=>S.genre==='rap',hasFr=()=>S.friends.some(f=>f.yak>=30),car=()=>S.cars&&S.cars.length>0,house=()=>!!S.house,pend=()=>typeof pendT==='function'&&pendT()>0,bot=()=>S.bot&&S.bot.on;
const K=(m)=>Math.round(m*(1+Math.pow(S.fame/40,2)));/* şöhrete göre ölçekli para */
