{const tops=['Bir hayran koluna adını dövme yaptırmış.','Bir çift ilk dansını senin şarkınla yapmış, videoyu gönderdiler.','Bir öğretmen sınıfta şarkını öğretmiş.','Bir hasta "şarkın beni ayakta tuttu" yazmış.','Bir asker nöbette senin şarkını dinliyormuş.','Bir anne bebeğine şarkınla ninni söylüyormuş.'];
 E({id:'fan_m',min:16,c:()=>fam(15)&&rel(),gen:()=>({m:pick(tops)}),t:'Hayran mesajı',x:p=>p.m,ch:[{t:'Paylaş',ok:{f:()=>R(200,3000),hp:4},lo:'Hikâye yayıldı.'},{t:'Özel cevap',ok:{hp:3},lo:'Kişisel teşekkür.'}]})}
{const news=['"Yeni albüm yolda mı?" diye sordu','"ünlü X ile görüntülendi" yazdı','"estetik yaptırdı" iddiasında bulundu','"servetini kaybetti" diye başlık attı','"sahneyi bırakıyor" dedi','"gizlice evlendi" yazdı'];
 E({id:'mag_t',min:18,c:()=>fam(30),gen:()=>({n:pick(news)}),t:'Magazin haberi',x:p=>`Bir magazin sitesi hakkında ${p.n}.`,ch:[{t:'Yalanla',ok:{f:()=>R(-500,1500)},lo:'Açıklama yaptın.'},{t:'Gül geç',ok:{hp:1,f:()=>R(0,800)},lo:'Umursamadın.'},{t:'Dava aç',ok:{m:-15000,f:300,hp:-1},lo:'Tekzip yayınlandı.'}]})}
{const asks=[['Hayır kurumu bağış konseri',{hp:5,f:2000,m:()=>-K(5000)}],['Üniversite bahar şenliği',{m:()=>K(20000),f:1500}],['Düğün performansı (zengin aile)',{m:()=>K(80000),hp:-1}],['Kurumsal yılbaşı partisi',{m:()=>K(60000),hp:-2}],['Belediye festivali',{m:()=>K(30000),f:1500}],['AVM açılışı',{m:()=>K(25000),f:500,hp:-2}]];
 E({id:'gig_t',min:18,c:()=>fam(25),gen:()=>({i:R(0,asks.length-1)}),t:'Özel davet',x:p=>`${asks[p.i][0]} için sahne teklifi geldi.`,ch:[{t:'Kabul et',ok:{fn:()=>{}},lo:'Sahne aldın.'},{t:'Reddet',ok:{},lo:'Reddettin.'}]});
 /* kabulde etkileri p üzerinden uygula */
 const ev=EVENTS.find(e=>e.id==='gig_t');ev.ch[0].fn=p=>{const a=asks[p.i][1],e={};Object.keys(a).forEach(k=>e[k]=typeof a[k]==='function'?a[k]():a[k]);evFx(e,`${asks[p.i][0]}: sahne aldın.`)}}
/* fonksiyon değerli etkileri çözümle */
{const _fx=evFx;evFx=function(e,msg,k){if(e){const o={};Object.keys(e).forEach(x=>o[x]=typeof e[x]==='function'&&x!=='fn'?e[x]():e[x]);e=o}return _fx(e,msg,k)}}
/* ================= olay sıklığı: her çeyrek 1–3 olay ================= */
{const _pe=pickEvents;pickEvents=function(){if(S&&S.cr&&S.cr.jail)return _pe();_pe();if(!S||S.age<5)return;S.evSeen=S.evSeen||{};
 const ok=e=>e.min<=S.age&&(e.max==null||S.age<=e.max)&&(!e.c||e.c())&&!recentEv(e.id)&&!(e.once&&S.evSeen[e.id]!=null)&&!S.evq.some(q=>q.id===e.id);
 const pool=EVENTS.filter(e=>!e.auto&&ok(e));const n=S.evq.length;const want=n===0?1:0;const extra=ch(.5)?1:0;const extra2=ch(.2)?1:0;
 for(let i=0;i<want+extra+extra2&&pool.length;i++){const e=pool.splice(Math.floor(Math.random()*pool.length),1)[0];S.evSeen[e.id]=S.qt;S.evq.push({id:e.id,p:e.gen?e.gen():{}})}}}
